 t jsonb:='{"A":["P009","P032","P022"],"B":["P011","P014","P029"],"C":["P015","P019","P026"]}';
 gs jsonb:=$J$[["A · Grupo 1","A",["C150","C146","C134","C145","C135","C153"]],["A · Grupo 2","C",["C132","C158","C128","C149","C157","C143"]],["A · Grupo 3","B",["C137","C160","C154","C142","C148","C152"]],["A · Grupo 4","A",["C129","C131","C147","C140","C139"]],["A · Grupo 5","C",["C144","C138","C130","C127","C133"]],["A · Grupo 6","B",["C156","C151","C159","C136","C141"]],["B · Grupo 1","B",["C171","C173","C174","C172","C184","C168"]],["B · Grupo 2","A",["C170","C166","C167","C188","C179","C175"]],["B · Grupo 3","C",["C164","C161","C189","C186","C169","C165"]],["B · Grupo 4","B",["C162","C185","C176","C180","C190"]],["B · Grupo 5","C",["C155","C183","C187","C182","C178"]],["B · Grupo 6","A",["C163","C126","C191","C177","C181"]],["C · Grupo 1","B",["C219","C215","C194","C209","C206","C200"]],["C · Grupo 2","A",["C203","C211","C210","C221","C204","C220"]],["C · Grupo 3","B",["C222","C202","C193","C212","C207","C218"]],["C · Grupo 4","C",["C196","C208","C223","C205","C201"]],["C · Grupo 5","A",["C195","C216","C199","C192","C224"]],["C · Grupo 6","C",["C214","C198","C217","C197","C213"]]]$J$;
begin
 if exists(select 1 from eem_grupos where carpeta_id='71625981-a76d-4e88-80b6-a1c049fe1212') or exists(select 1 from eem_entregas where carpeta_id='71625981-a76d-4e88-80b6-a1c049fe1212') then raise exception 'FORMULACIÓN DE PROYECTOS ya no está vacía'; end if;
 perform fn_eem_f1_actor('P030',null,null,'normal','Reemplazada por ELABORACIÓN DE PROYECTOS (Anexo A)');
 perform fn_eem_f1_carpeta_config('71625981-a76d-4e88-80b6-a1c049fe1212',null,'cerrada',null,null,null,'P030');
 v_c:=fn_eem_configurar('P030',$J${"materia":"ELABORACIÓN DE PROYECTOS","codigo":"EM-AU-FE-01","gestion":2026,"ciclo":2,"paralelo":null,"evaluador_id":"P017","fecha_limite":"2026-10-22T08:30:00-04:00","items":[{"bloque":"FORMA","sub_bloque":"","orden":1,"descripcion":"Cumple con las normas tipográficas.","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FORMA","sub_bloque":"","orden":2,"descripcion":"Considera el formato para la Elaboración de un Proyecto.","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Aspectos generales del proyecto","orden":1,"descripcion":"Nombre del Proyecto","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Aspectos generales del proyecto","orden":2,"descripcion":"Entidad ejecutora del Proyecto","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Aspectos generales del proyecto","orden":3,"descripcion":"Dirección","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":4,"descripcion":"Localización del Proyecto","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":5,"descripcion":"Caracteristicas de la Población","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":6,"descripcion":"Servicios existentes","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":7,"descripcion":"Acceso a la población","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":8,"descripcion":"Existencia actual del servicio o infraestructura","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":9,"descripcion":"Como sustituyen la falta de servicio o infraestructura","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":10,"descripcion":"Información adicional","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","orden":11,"descripcion":"Descripción del problema","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":12,"descripcion":"Tipo de proyecto.","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":13,"descripcion":"Descripción del proyecto","valor_pct":6,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":14,"descripcion":"Dimensionamiento","valor_pct":5,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":15,"descripcion":"Inversión estimada y financiamiento","valor_pct":5,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":16,"descripcion":"Costos de operación y mantenimiento de un año y financiamiento","valor_pct":4,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":17,"descripcion":"Participación de la comunidad","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":18,"descripcion":"Indicadores de beneficio","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Solución planteada como proyecto","orden":19,"descripcion":"Información adicional","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Conclusiones y recomendaciones","orden":20,"descripcion":"Recomendación técnica","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Conclusiones y recomendaciones","orden":21,"descripcion":"Justificación","valor_pct":3,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Conclusiones y recomendaciones","orden":22,"descripcion":"Fecha de elaboración","valor_pct":1,"modo_calificacion":"ia"},{"bloque":"FONDO","sub_bloque":"Conclusiones y recomendaciones","orden":23,"descripcion":"Responsable, Nombre y cargo","valor_pct":2,"modo_calificacion":"ia"},{"bloque":"EXPOSICION","sub_bloque":"PRESENTACIÓN DEL PROYECTO","orden":1,"descripcion":"Impresión prolija (Tamaño y tipo de papel).","valor_pct":2},{"bloque":"EXPOSICION","sub_bloque":"EXPOSICIÓN, DEFENSA Y SUSTENTACIÓN GRUPAL","orden":2,"descripcion":"Tienen conocimiento, exponen y sustentan la investigación y propuesta realizada, considerando los conocimientos básicos sobre la elaboración de Proyectos.","valor_pct":15},{"bloque":"EXPOSICION","sub_bloque":"EXPOSICIÓN, DEFENSA Y SUSTENTACIÓN GRUPAL","orden":3,"descripcion":"Emplean adecuadamente las técnicas de plataforma.","valor_pct":10},{"bloque":"EXPOSICION","sub_bloque":"EXPOSICIÓN, DEFENSA Y SUSTENTACIÓN GRUPAL","orden":4,"descripcion":"Responden con coherencia y seguridad a las preguntas realizadas por el tribunal.","valor_pct":10}],"perfil":{"hoja":"carta","hoja_cm":{"alto":27.94,"ancho":21.59},"tamano_pt":12,"alineacion":"justificado","margenes_cm":{"der":2,"inf":2,"izq":3,"sup":2},"interlineado":1.5,"clasificacion":"RESERVADO","entrega_autogrupo":false,"fuentes_permitidas":["Arial"],"sangria_francesa_cm":1,"impresion_presencial":true,"fuente_estructura":"TEXTO PROYECTOS 2026 (Cap. II y III: Perfil Mínimo de Proyectos en el ámbito militar) · ANEXO A PROYECTOS 2026","fuente_tipografia":"Perfil ECEME existente (igual que Elaboración de Planes); el texto de Proyectos no fija medidas tipográficas.","estructura_obligatoria":["ASPECTOS GENERALES DEL PROYECTO","IDENTIFICACIÓN DEL PROBLEMA A SOLUCIONAR O POTENCIALIDAD A DESARROLLAR","SOLUCIÓN PLANTEADA COMO PROYECTO","CONCLUSIONES Y RECOMENDACIONES"],"fondo":{"items":{"1":{"frases":["nombre del proyecto"]},"2":{"frases":["entidad ejecutora del proyecto"]},"3":{"frases":["dirección"]},"4":{"frases":["localización del proyecto"]},"5":{"frases":["caracteristicas de la población"]},"6":{"frases":["servicios existentes"]},"7":{"frases":["acceso a la población"]},"8":{"frases":["existencia actual del servicio o infraestructura"]},"9":{"frases":["como sustituyen la falta de servicio o infraestructura"]},"10":{"frases":["información adicional"]},"11":{"frases":["descripción del problema"]},"12":{"frases":["tipo de proyecto"]},"13":{"frases":["descripción del proyecto"]},"14":{"frases":["dimensionamiento"]},"15":{"frases":["inversión estimada y financiamiento"]},"16":{"frases":["costos de operación y mantenimiento de un año y financiamiento"]},"17":{"frases":["participación de la comunidad"]},"18":{"frases":["indicadores de beneficio"]},"19":{"frases":["información adicional"]},"20":{"frases":["recomendación técnica"]},"21":{"frases":["justificación"]},"22":{"frases":["fecha de elaboración"]},"23":{"frases":["responsable, nombre y cargo"]}}},"guia_metodologica":"PERFIL MÍNIMO DE PROYECTOS EN EL ÁMBITO MILITAR (TEXTO PROYECTOS 2026, CAP. III)\nEl perfil tiene cuatro partes obligatorias, en este orden:\nPARTE 1 ASPECTOS GENERALES DEL PROYECTO. Identifica la idea de proyecto.\n- Nombre del proyecto: menciona la acción, el objeto y la ubicación precisa (ej. \"Construcción de una cancha multifuncional en Sorata\").\n- Entidad ejecutora: denominación oficial de la unidad, gran unidad, instituto o repartición militar que ejecutará el proyecto, su ubicación institucional y responsabilidad.\n- Dirección / entidad operadora: organización militar que operará, administrará y mantendrá el proyecto una vez concluido; responsable y dependencias que participan.\nPARTE 2 IDENTIFICACIÓN DEL PROBLEMA QUE SE DESEA SOLUCIONAR O POTENCIALIDAD A DESARROLLAR. Diagnóstico de la situación actual que distingue causas de efectos.\n- Localización: comunidad o zona, municipio y departamento; define el área de influencia.\n- Características de la población: número de habitantes, tasa de crecimiento, nivel de educación promedio y principal actividad económica.\n- Servicios existentes: cobertura (porcentaje o cantidad) y calidad (bueno, regular, malo).\n- Acceso a la población: vías de acceso y su estado; efecto sobre costos o alternativas.\n- Existencia actual del servicio o infraestructura: si existe, características técnicas, estado, disponibilidad y cobertura.\n- Cómo sustituyen la falta del servicio o infraestructura: cómo se cubre hoy la necesidad.\n- Información adicional relevante para identificar el problema.\n- Descripción del problema: resumen completo del diagnóstico; por qué ampliar, mejorar o crear el servicio o infraestructura.\nPARTE 3 SOLUCIÓN PLANTEADA COMO PROYECTO. Características generales, costos y beneficios.\n- Tipo de proyecto: construcción nueva, equipamiento, ampliación, refacción u otro (especificado).\n- Descripción del proyecto: obra, tamaño, servicios a prestar; normalmente detallada en un ANEXO.\n- Dimensionamiento: plano de ubicación de la población a atender (ANEXO), población actualmente atendida y población a atender con el proyecto.\n- Inversión estimada y financiamiento: cuadro en Bs con terreno, edificaciones, equipamiento, preinversión (aprox. 5%), supervisión (aprox. 5%) e imprevistos (aprox. 10%); importe y fuentes (aporte propio, aporte comunidad, crédito, donación). La suma de las fuentes debe ser igual al importe total.\n- Costos de operación y mantenimiento de un año y financiamiento: personal técnico, personal administrativo, servicios básicos, materiales y suministros; fuentes (ingresos de operación, transferencias del gobierno, recursos propios); fila de totales que cuadra.\n- Participación de la comunidad: forma de participación en construcción o funcionamiento, en cantidades, valores y formas de efectivización.\n- Indicadores de beneficio: personas beneficiadas, costo de inversión por persona beneficiada (costo total / beneficiarios) y otros.\n- Información adicional que permita decidir la conveniencia del proyecto.\nPARTE 4 CONCLUSIONES Y RECOMENDACIONES.\n- Recomendación técnica: marca una alternativa (continuar el estudio, postergar el estudio o abandonar el proyecto).\n- Justificación: explica por qué, a partir del análisis de las partes 1 a 3.\n- Fecha de elaboración del perfil.\n- Responsable: nombre, cargo y firma de quien asume la recomendación."}}$J$);
 perform fn_eem_f1_banda(v_c,'texto_65',58,63,'reescalado',true,'Documento entre 58 y 63 (igual que Elaboración de Planes)','P030');
 v_r:=fn_eem_f1_importar_grupos(v_c,(select jsonb_agg(jsonb_build_object('numero',o,'nombre',x->>0,'integrantes',(select jsonb_agg(jsonb_build_object('cursante_id',c,'es_jefe',false)) from jsonb_array_elements_text(x->2) c))) from jsonb_array_elements(gs) with ordinality e(x,o)),true,'P030');
 if (v_r->>'grupos_creados')::int<>18 or (v_r->>'asignados')::int<>99 then raise exception 'Importación inesperada: %',v_r; end if;
 for g in select * from jsonb_array_elements(gs) loop
  select id into strict v_g from eem_grupos where carpeta_id=v_c and nombre=g->>0;
  for p in select * from jsonb_array_elements_text(t->(g->>1)) loop
   perform fn_eem_f4_designar(v_c,p,'grupo',null,v_g,false,true,null,'P030'); n:=n+1;
  end loop;
 end loop;
 if n<>54 then raise exception 'Designaciones: %',n; end if;
 perform fn_eem_f5_config_guardar(v_c,$J${"lugar":"Cochabamba","unidad_competencia":"ELABORACIÓN DE PROYECTOS","ciclo_texto":"SEGUNDO","ciclo_profesor_id":"P017","jefe_profesor_id":"P008"}$J$,'P030');
 perform fn_eem_ia_referencia(v_c,'P030',($J$"RÚBRICA OFICIAL — ANEXO A: UNIDAD DE COMPETENCIA ELABORACIÓN DE PROYECTOS (2DO CICLO 2026). Documento escrito 63% = Forma 3% + Fondo 60%. La exposición, defensa y sustentación grupal (37%) la califica el tribunal, no la IA. Los criterios y sus valores son los de la rúbrica de la carpeta.\n\nPERFIL MÍNIMO DE PROYECTOS EN EL ÁMBITO MILITAR (TEXTO PROYECTOS 2026, CAP. III)\nEl perfil tiene cuatro partes obligatorias, en este orden:\nPARTE 1 ASPECTOS GENERALES DEL PROYECTO. Identifica la idea de proyecto.\n- Nombre del proyecto: menciona la acción, el objeto y la ubicación precisa (ej. \"Construcción de una cancha multifuncional en Sorata\").\n- Entidad ejecutora: denominación oficial de la unidad, gran unidad, instituto o repartición militar que ejecutará el proyecto, su ubicación institucional y responsabilidad.\n- Dirección / entidad operadora: organización militar que operará, administrará y mantendrá el proyecto una vez concluido; responsable y dependencias que participan.\nPARTE 2 IDENTIFICACIÓN DEL PROBLEMA QUE SE DESEA SOLUCIONAR O POTENCIALIDAD A DESARROLLAR. Diagnóstico de la situación actual que distingue causas de efectos.\n- Localización: comunidad o zona, municipio y departamento; define el área de influencia.\n- Características de la población: número de habitantes, tasa de crecimiento, nivel de educación promedio y principal actividad económica.\n- Servicios existentes: cobertura (porcentaje o cantidad) y calidad (bueno, regular, malo).\n- Acceso a la población: vías de acceso y su estado; efecto sobre costos o alternativas.\n- Existencia actual del servicio o infraestructura: si existe, características técnicas, estado, disponibilidad y cobertura.\n- Cómo sustituyen la falta del servicio o infraestructura: cómo se cubre hoy la necesidad.\n- Información adicional relevante para identificar el problema.\n- Descripción del problema: resumen completo del diagnóstico; por qué ampliar, mejorar o crear el servicio o infraestructura.\nPARTE 3 SOLUCIÓN PLANTEADA COMO PROYECTO. Características generales, costos y beneficios.\n- Tipo de proyecto: construcción nueva, equipamiento, ampliación, refacción u otro (especificado).\n- Descripción del proyecto: obra, tamaño, servicios a prestar; normalmente detallada en un ANEXO.\n- Dimensionamiento: plano de ubicación de la población a atender (ANEXO), población actualmente atendida y población a atender con el proyecto.\n- Inversión estimada y financiamiento: cuadro en Bs con terreno, edificaciones, equipamiento, preinversión (aprox. 5%), supervisión (aprox. 5%) e imprevistos (aprox. 10%); importe y fuentes (aporte propio, aporte comunidad, crédito, donación). La suma de las fuentes debe ser igual al importe total.\n- Costos de operación y mantenimiento de un año y financiamiento: personal técnico, personal administrativo, servicios básicos, materiales y suministros; fuentes (ingresos de operación, transferencias del gobierno, recursos propios); fila de totales que cuadra.\n- Participación de la comunidad: forma de participación en construcción o funcionamiento, en cantidades, valores y formas de efectivización.\n- Indicadores de beneficio: personas beneficiadas, costo de inversión por persona beneficiada (costo total / beneficiarios) y otros.\n- Información adicional que permita decidir la conveniencia del proyecto.\nPARTE 4 CONCLUSIONES Y RECOMENDACIONES.\n- Recomendación técnica: marca una alternativa (continuar el estudio, postergar el estudio o abandonar el proyecto).\n- Justificación: explica por qué, a partir del análisis de las partes 1 a 3.\n- Fecha de elaboración del perfil.\n- Responsable: nombre, cargo y firma de quien asume la recomendación."$J$::jsonb)#>>'{}','ANEXO A PROYECTOS 2026 + TEXTO PROYECTOS 2026');
end $do$;
